// Compares our byte output with fixtures generated by the reference implementation
// (tools/make_fixtures.py → pypixelcolor).
import { describe, expect, it } from 'vitest';
import fixtures from './fixtures.json';
import * as P from '../src/protocol/ipixel';
import { crc32 } from '../src/protocol/crc32';

const FIXED = new Date(2026, 9, 21, 16, 45, 7);
const hexOf = (plan: P.SendPlan) => plan.windows.map((w) => P.hex(w.data));
const fromHex = (h: string) => Uint8Array.from(h.match(/../g) ?? [], (b) => parseInt(b, 16));
const rgb = (h: string) => [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16)) as [number, number, number];

function glyphFromFixture(ch: string): P.Glyph {
  const g = (fixtures.glyphs as Record<string, { width: number; rows: string[] }>)[ch];
  return { width: g.width, height: g.rows.length, pixels: g.rows.join('').split('').map((c) => c === '#') };
}

describe('simple commands', () => {
  const c = fixtures.commands;
  it.each([
    ['brightness_42', P.setBrightness(42)],
    ['power_on', P.setPower(true)],
    ['power_off', P.setPower(false)],
    ['orientation_2', P.setOrientation(2)],
    ['clear', P.clearAll()],
    ['delete_3', P.deleteSlot(3)],
    ['show_5', P.showSlot(5)],
    ['time', P.setTime(FIXED)],
    ['clock_3_24_date', P.setClockMode(3, true, true, FIXED)],
    ['timer_start', P.setStopwatch(P.TimerAction.Start)],
    ['scores_7_12', P.setScores(7, 12)],
    ['fun_on', P.setFunMode(true)],
    ['pixel', P.setPixel(5, 9, 0xff, 0x80, 0x00)],
  ] as const)('%s', (name, plan) => {
    expect(hexOf(plan)).toEqual((c as Record<string, string[]>)[name]);
  });
});

describe('image transfer', () => {
  for (const [name, f] of Object.entries(fixtures.images)) {
    it(name, () => {
      const plan = P.sendImage(fromHex(f.payload), f.gif, f.slot);
      expect(plan.windows.length).toBe(f.windows.length);
      expect(hexOf(plan)).toEqual(f.windows);
    });
  }
});

describe('text transfer', () => {
  it('crc32 matches zlib', () => {
    expect(crc32(new TextEncoder().encode('123456789'))).toBe(0xcbf43926);
  });
  for (const [name, f] of Object.entries(fixtures.texts)) {
    it(name, () => {
      const glyphs = Array.from(f.text).map(glyphFromFixture);
      const plan = P.sendText(glyphs, {
        animation: f.animation, speed: f.speed, rainbow: f.rainbow,
        color: rgb(f.color), background: f.bg ? rgb(f.bg) : null, slot: f.slot,
      });
      expect(hexOf(plan)).toEqual(f.windows);
    });
  }
});

describe('notifications', () => {
  it('classifies ACK frames', () => {
    expect(P.classifyNotification(Uint8Array.of(5, 0, 1, 0, 3))).toEqual({ kind: 'ack', code: 3 });
    expect(P.classifyNotification(Uint8Array.of(9, 0, 1, 0x80, 132, 1, 2, 3, 4, 5, 255)).kind).toBe('data');
  });
  it('parses 96x16 device info', () => {
    const info = P.parseDeviceInfo(Uint8Array.of(9, 0, 1, 0x80, 132, 1, 2, 3, 4, 5, 255));
    expect([info.width, info.height]).toEqual([96, 16]);
  });
});
